Упражнение 1

Напишите программу, которая c помощью циклов **for** и **while** выводит на консоль пять раз строку "Hello Work".

 Ответ

```c
#include <stdio.h>

int main(void)
{
	for(int i=0; i < 5; i++)
	{
		printf("Hello Work\n");
	}

	int count = 0;
	while(count < 5)
	{
		printf("Hello Work\n");
		count++;
	}

	return 0;
}
```

 Упражнение 2

Напишите программу, которая с помощью цикла **for** выводит в одну строку все **нечетные числа** от 11 до 20.

 Ответ

```c
#include <stdio.h>

int main(void)
{
	for(int i=11; i < 20; i++)
	{
		if(i % 2 == 1)	// если остаток от деления на 2 равен 1, то число нечетное
		{
			printf("%d ", i);
		}

	}
	return 0;
}
```

 Упражнение 3

Напишите программу, которая выводит на консоль следующее:

```bash
*     *
 *   * 
  * *  
   *   
  * *  
 *   * 
*     *
```

 Ответ

```c
#include <stdio.h>

int main(void)
{
    int n = 7;
    for(int i =0; i < n; i++){
        for(int j = 0; j< n; j++){
            if(j==i || j == n-i-1) printf("*");
            else printf(" ");
        }
        printf("\n");
    }
    return 0;
}
```

 Упражнение 4

Напишите программу, которая выводит на консоль следующее:

```bash
*******
 *   * 
  * *  
   *   
  * *  
 *   * 
*******
```

 Ответ

```c
#include <stdio.h>

int main(void)
{
    int n = 7;
    for(int i =0; i < n; i++){
        for(int j = 0; j< n; j++){
            if(i == 0 || i == n-1 || j==i || j == n-i-1) printf("*");
            else printf(" ");
        }
        printf("\n");
    }
    return 0;
}
```

